import { invoiceTotals, lineTotal } from './invoices.js';
import { roundCents } from './money.js';

export function overdueInvoices(invoices, asOf) {
  const overdue = [];

  for (const invoice of invoices) {
    // Only include invoices with status 'issued' or 'partially_paid'
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
      continue;
    }

    // Check if dueDate is before asOf
    if (invoice.dueDate >= asOf) {
      continue;
    }

    // Calculate due amount
    const totalsResult = invoiceTotals(invoice);
    const due = totalsResult.ok ? totalsResult.value.total : 0;

    // Calculate days overdue
    const dueDateObj = new Date(invoice.dueDate + 'T00:00:00Z');
    const asOfObj = new Date(asOf + 'T00:00:00Z');
    const daysOverdue = Math.floor((asOfObj - dueDateObj) / (1000 * 60 * 60 * 24));

    overdue.push({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue,
      due,
    });
  }

  // Sort by daysOverdue descending (most overdue first = longest overdue)
  overdue.sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const rate = line.vatRate ?? 0;
      const lineGrossTotal = lineTotal(line);
      const discountPercent = line.discountPercent ?? 0;
      const lineDiscount = roundCents(lineGrossTotal * discountPercent / 100);
      const lineAmount = Math.max(0, lineGrossTotal - lineDiscount);
      const lineVat = roundCents(lineAmount * rate / 100);

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { base: 0, vat: 0 });
      }
      const entry = vatMap.get(rate);
      entry.base += lineAmount;
      entry.vat += lineVat;
    }
  }

  const result = Array.from(vatMap, ([rate, { base, vat }]) => ({ rate, base, vat }));
  result.sort((a, b) => b.rate - a.rate);

  return result;
}

